"""A local copy of the acceptance test (instruction.md), for checking the delivery before hand-in.
    python3 grader.py movement.json|variant_6h.json [quick] [only=mesh,print,asm,...]"""
import json, math, os, sys, hashlib, itertools, time
from fractions import Fraction
from multiprocessing import Pool
import numpy as np
import manifold3d as m3
from gearlib import APP, kernel, rot_about, mesh_test

OUT = os.path.join(APP, "delivery")
CACHE = os.environ.get("PART_CACHE", "/tmp/claude-0/-tmp-claude-0-runs-smoke1-fable-app/84db1fc9-c179-44df-8c22-168c06b406bb/scratchpad/cache")
os.makedirs(CACHE, exist_ok=True)
TOL = 0.01

def load(name):
    if name == "barrel":
        return kernel.tris_to_part(kernel.read_stl(APP + "/supplied/barrel.stl", 10**7, 10**9), 0.005)
    p = os.path.join(OUT, "parts", name + ".step")
    st = os.stat(p)
    key = hashlib.md5(("%s-%d-%d" % (name, st.st_size, st.st_mtime_ns)).encode()).hexdigest()
    c = os.path.join(CACHE, key + ".npy")
    if os.path.exists(c):
        tris = np.load(c)
    else:
        tris = kernel.read_step(p, 16777216, 200000, 0.001, 0.1, 500, 120, 4096)
        np.save(c, tris)
    return kernel.tris_to_part(tris, 0.005)

G = {}
def setup(movfile):
    mov = json.load(open(os.path.join(OUT, movfile)))
    G["mov"] = mov
    G["parts"] = {}
    for n in mov["fixed"]:
        G["parts"][n] = load(n)
    G["mob"] = {"barrel": load("barrel")}
    G["axis"] = {"barrel": (0.0, 0.0)}
    for k, m in mov["mobiles"].items():
        for n in m["parts"]:
            G["parts"][n] = load(n)
        G["mob"][k] = kernel.union([G["parts"][n] for n in m["parts"]])
        G["axis"][k] = tuple(m["axis"])
    G["frame"] = kernel.union([G["parts"][n] for n in mov["fixed"]])
    return mov

def speeds(mov, period_h):
    sp = {"barrel": Fraction(-1, period_h)}        # turns per hour, clockwise negative
    ok = True
    ch = True
    while ch:
        ch = False
        for e in mov["meshes"]:
            for a, b, za, zb in ((e["driver"], e["driven"], e["driver_teeth"], e["driven_teeth"]),
                                 (e["driven"], e["driver"], e["driven_teeth"], e["driver_teeth"])):
                if a in sp:
                    v = -sp[a] * Fraction(za, zb)
                    if b not in sp:
                        sp[b] = v; ch = True
                    elif sp[b] != v:
                        ok = False
    return sp, ok

def t_mesh(args):
    i, sh, quick = args
    e = G["mov"]["meshes"][i]
    ok, w = mesh_test(G["mob"][e["driver"]], G["mob"][e["driven"]], G["axis"][e["driver"]], G["axis"][e["driven"]],
                      e["driver_teeth"], e["driven_teeth"], sh, quick)
    return ("mesh %s>%s shift %+.2f" % (e["driver"], e["driven"], sh), ok,
            "jam %.5f gap %.4f area %.4f/%.4f vol %.4f" % (w["jam"], w["gap"], w["area"], w["need_area"], w["vol"]))

def t_free(k):
    worst = 0.0
    for s in range(72):
        worst = max(worst, kernel.ivol(rot_about(G["mob"][k], G["axis"][k], 5.0 * s), G["frame"]))
    return ("free %s" % k, worst <= TOL, "%.5f" % worst)

def t_pair(args):
    a, b, sa, sb = args
    A, B = G["mob"][a], G["mob"][b]
    fa, fb = float(sa), float(sb)
    worst = 0.0
    fast = max(abs(fa), abs(fb))
    seqs = []
    if fast > 0:
        seqs.append([(360.0 * fa / fast * s / 144, 360.0 * fb / fast * s / 144) for s in range(144)])
        if fa != fb:
            rel = abs(fa - fb)
            seqs.append([(360.0 * fa / rel * s / 144, 360.0 * fb / rel * s / 144) for s in range(144)])
    else:
        seqs.append([(0, 0)])
    for seq in seqs:
        for ra, rb in seq:
            worst = max(worst, kernel.ivol(rot_about(A, G["axis"][a], ra), rot_about(B, G["axis"][b], rb)))
    return ("pair %s/%s" % (a, b), worst <= TOL, "%.5f" % worst)

def t_print(n):
    man = G["parts"][n]
    h = 0.05
    bb = man.bounding_box()
    lo = np.array(bb[:3]); hi = np.array(bb[3:])
    k0 = np.floor((lo - 0.0113) / h) - 2
    origin = k0 * h + 0.0113 - h / 2
    shape = tuple(int(v) for v in (np.ceil((hi - origin) / h) + 2))
    npieces, dev = kernel.opening_test_slabs(man, origin, shape, h, 1.5, 1.0, 6.0)
    return ("print %s" % n, npieces >= 1 and dev <= 4.0 + 1e-9, "pieces %d dev %.2f vox" % (npieces, dev))

def t_asm(name):
    asm = G["asm"]; order = G["order"]
    P = asm["paths"].get(name)
    sol = G["asmparts"][name]
    idx = order.index(name)
    before = order[:idx] + G["notinorder"]
    if not isinstance(P, list) or not (2 <= len(P) <= 1500):
        return ("asm " + name, False, "pose count")
    Ps = np.array(P, float)
    if Ps.shape[1:] != (4, 4) or not np.isfinite(Ps).all():
        return ("asm " + name, False, "matrix")
    for Tm in Ps:
        R = Tm[:3, :3]
        if abs(R.T @ R - np.eye(3)).max() > 1e-6 or abs(np.linalg.det(R) - 1) > 1e-6 or abs(Tm[3] - [0, 0, 0, 1]).max() > 1e-6:
            return ("asm " + name, False, "not rigid")
    if abs(Ps[-1] - np.eye(4)).max() > 1e-6:
        return ("asm " + name, False, "last pose")
    V = kernel.verts(sol)
    Vh = np.c_[V, np.ones(len(V))]
    prev = None
    for Tm in Ps:
        cur = (Vh @ Tm.T)[:, :3]
        if prev is not None and np.linalg.norm(cur - prev, axis=1).max() > 0.2:
            return ("asm " + name, False, "step too long")
        prev = cur
    first = (Vh @ Ps[0].T)[:, :3]
    lo, hi = G["bbox"]
